package com.lingualearn.app.data.content

/**
 * Hindi (hi), Tamil (ta), and Telugu (te) comprehensive curriculum content.
 * 10 levels × 6 topics = 60 distinct lessons per language.
 */
object HindiCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("नमस्ते! / सुप्रभात", "Namaste! / Good morning", "nuh-muhs-TAY / soo-pruh-BHAAT", "नमस्ते! आप सब कैसे हैं?", "Namaste! How are you all?", "Joining hands in Namaste conveys respect for the soul within.")
                "Introducing Yourself" -> CurriculumLessonContent("मेरा नाम राहुल है", "My name is Rahul", "MAY-raa naam RAA-hool hai", "मेरा नाम राहुल है और मैं दिल्ली से हूँ।", "My name is Rahul and I am from Delhi.", "'Mera naam' (my name) is the polite introduction.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("हाँ / नहीं / कृपया / धन्यवाद", "Yes / No / Please / Thank you", "haan / nuh-HEEN / KRIP-yaa / DHUHN-yuh-vaad", "हाँ, कृपया मेरी मदद कीजिए। धन्यवाद!", "Yes, please help me. Thank you!", "'Dhanyavaad' or 'Shukriya' express sincere gratitude.")
                "Numbers 1–10" -> CurriculumLessonContent("एक, दो, तीन, चार, पाँच...", "1 to 10 numerals", "ayk, doh, teen, chaar, paanch", "मुझे दो कप चाय चाहिए।", "I need two cups of tea, please.", "Chai stalls throughout India count in Hindi numerals.")
                "Basic Pronouns" -> CurriculumLessonContent("मैं, तुम, आप, हम, वे", "I, you (informal), you (formal), we, they", "main, toom, aap, hum, vay", "हम सब मिलकर हिंदी सीख रहे हैं।", "We are all learning Hindi together.", "'Aap' is polite and respectful; 'tum' is for close peers.")
                else -> CurriculumLessonContent("माफ़ कीजिए और फिर मिलेंगे", "Excuse me / Sorry and See you again", "MAAF kee-jee-yay / PHIR mee-LENG-ay", "माफ़ कीजिए, क्या आप मुझे रास्ता बता सकते हैं?", "Excuse me, could you show me the way?", "'Phir milenge' is the heartwarming way to say goodbye.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("परिवार (माता-पिता, भाई, बहन)", "Family (parents, brother, sister)", "puh-ree-VAAR", "मेरा बड़ा भाई और छोटी बहन मुंबई में रहते हैं।", "My elder brother and younger sister live in Mumbai.", "Hindi distinguishes elder (bada) and younger (chhota) siblings.")
                "Colors" -> CurriculumLessonContent("लाल, नीला, पीला, हरा, सफ़ेद", "Red, Blue, Yellow, Green, White", "laal, NEE-laa, PEE-laa, HUH-raa, suh-FAYD", "मुझे वह नीला कुर्ता बहुत पसंद है।", "I like that blue kurta very much.", "Colors ending in '-aa' inflect with gender and case.")
                "Food" -> CurriculumLessonContent("दाल, रोटी, चावल और सब्ज़ी", "Lentils, flatbread, rice, and vegetables", "daal, ROH-tee, CHAA-vuhl", "गरमा-गरम दाल मखनी और रोटी बहुत स्वादिष्ट हैं।", "Hot dal makhani and roti are very delicious.", "Traditional Indian meals balance six distinct Ayurvedic tastes.")
                "Days & Months" -> CurriculumLessonContent("सोमवार से रविवार तक", "Monday to Sunday", "sohm-VAAR say ruh-vee-VAAR", "हम रविवार को परिवार के साथ घूमने जाएँगे।", "We will go out with family on Sunday.", "Days of the week are named after celestial planets (Surya, Chandra).")
                "Simple Questions" -> CurriculumLessonContent("कौन? क्या? कहाँ? कब? क्यों?", "Who? What? Where? When? Why?", "kohn, kyaa, kuh-HAAN, kub, kyohn", "रेलवे स्टेशन यहाँ से कितनी दूर है?", "How far is the railway station from here?", "In Hindi questions, the question word precedes the verb.")
                else -> CurriculumLessonContent("खाना, पीना, आना, जाना", "Eat, drink, come, go", "KHAA-naa, PEE-naa, AA-naa, JAA-naa", "हम शाम को पार्क में घूमने जाते हैं।", "We go for a walk in the park in the evening.", "Infinitive verbs in Hindi end with '-naa'.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("सुबह जल्दी उठना और व्यायाम", "Waking up early and exercising", "SOO-buh juhl-DEE ooth-NAA", "मैं रोज़ सुबह छह बजे उठता हूँ।", "I wake up at six o'clock every morning.", "Present habitual uses masculine '-taa hoon' or feminine '-tee hoon'.")
                "Shopping" -> CurriculumLessonContent("यह कितने का है?", "How much does this cost?", "yuh KIT-nay kaa hai", "भैया, यह कुरता कितने का है? थोड़ा कम कीजिए।", "Brother, how much is this kurta? Please lower it a bit.", "Bargaining politely is a common social practice in local bazaars.")
                "Time" -> CurriculumLessonContent("अभी क्या समय हुआ है?", "What time is it right now?", "uh-BHEE kyaa SUH-muy", "अभी दोपहर के ढाई बजे हैं।", "It is 2:30 in the afternoon right now.", "Hindi has unique words for halves: 'dedh' (1:30) and 'dhaai' (2:30).")
                "Directions" -> CurriculumLessonContent("सीधे जाइए और दाएँ मुड़िए", "Go straight and turn right", "SEE-dhay JAA-ee-yay", "यहाँ से सीधे जाकर चौराहे से बाएँ मुड़िए।", "Go straight from here and turn left at the intersection.", "'Daayein' is right, 'baayein' is left.")
                "Simple Sentences" -> CurriculumLessonContent("मैं एक कप चाय पीना चाहता हूँ", "I want to drink a cup of tea", "CHAA-huh-taa hoon", "मैं शाम को दोस्तों के साथ गपशप करना चाहता हूँ।", "I want to chat with friends in the evening.", "Pattern: Verb root + 'chaahtaa/chaahtee hoon'.")
                else -> CurriculumLessonContent("और बताइए, सब कैसा चल रहा है?", "Tell me, how is everything going?", "owr buh-TAA-ee-yay", "सब बढ़िया है, आपकी कृपा है।", "Everything is great, thanks to your kindness.", "Warm colloquial Hindi small-talk opener.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("कल मैं ताज महल देखने गया था", "Yesterday I went to see the Taj Mahal", "kul main TAAJ muh-HUL", "कल हमने आगरा में ताज महल का दीदार किया।", "Yesterday we marveled at the Taj Mahal in Agra.", "Past tense inflects for gender: 'gayaa thaa' / 'gayee thee'.")
                "Future Plans" -> CurriculumLessonContent("अगले महीने हम जयपुर जाएँगे", "Next month we will go to Jaipur", "UG-lay muh-HEE-nay", "दीवाली की छुट्टियों में हम अपने गाँव जाएँगे।", "During Diwali holidays we will go to our hometown.", "Future suffix ends with '-oongaa/-ayngay'.")
                "Travel" -> CurriculumLessonContent("भारतीय रेल और यात्रा", "Indian Railways and journey", "BHAA-ruh-teey rayl", "हमारी राजधानी एक्सप्रेस समय पर रवाना हो रही है।", "Our Rajdhani Express is departing on time.", "Indian Railways connects the length and breadth of the subcontinent.")
                "Restaurants" -> CurriculumLessonContent("बिल ले आइए, कृपया", "Please bring the bill", "bil lay AA-ee-yay", "भोजन बहुत लजीज था, कृपया बिल ले आइए।", "The food was delicious, please bring the bill.", "Calling the server 'Bhaiya' (brother) is friendly and ubiquitous.")
                "Describing People" -> CurriculumLessonContent("मेहनती, मिलनसार और दयालु", "Hardworking, sociable, and compassionate", "MEH-nuh-tee / mee-lun-SAAR", "मेरी दादी बहुत दयालु और ममतामयी हैं।", "My grandmother is very compassionate and full of maternal love.", "Indian culture places tremendous reverence on elders.")
                else -> CurriculumLessonContent("आज मौसम बहुत सुहावना है", "The weather is very pleasant today", "MOW-sum soo-HAAV-naa", "हल्की-हल्की बारिश से मौसम खुशनुमा हो गया है।", "The light drizzle has made the weather delightful.", "Rain brings immense celebration after hot Indian summers.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("क्या मैं अपनी राय रख सकता हूँ?", "May I share my opinion?", "RAA-ee rukh SUHK-taa", "इस महत्वपूर्ण विषय पर मैं अपना विचार व्यक्त करना चाहता हूँ।", "On this important topic, I would like to express my view.", "Formal conversational register uses 'vyakt karnaa'.")
                "Opinions" -> CurriculumLessonContent("मेरे विचार में योग और ध्यान", "In my view, yoga and meditation", "MAY-ray vee-CHAAR", "मेरे विचार में योग से शारीरिक और मानसिक शांति मिलती है।", "In my view, yoga brings physical and mental peace.", "'Mere vichaar mein' introduces opinions with dignity.")
                "Experiences" -> CurriculumLessonContent("पहाड़ों में बिताए यादगार दिन", "Memorable days spent in the mountains", "PAH-haa-dohn mein", "हिमालय की वादियों में बिताए दिन अविस्मरणीय थे।", "The days spent in the Himalayan valleys were unforgettable.", "Reflecting on travel and life experiences.")
                "Comparisons" -> CurriculumLessonContent("दिल्ली मुंबई से अधिक ठंडी है", "Delhi is colder than Mumbai", "uh-DHIK thun-dee", "सर्दियों में दिल्ली मुंबई की तुलना में कहीं अधिक ठंडी होती है।", "In winter, Delhi is far colder in comparison to Mumbai.", "'Ki tulnaa mein' signifies 'in comparison with'.")
                "More Complex Grammar" -> CurriculumLessonContent("अगर... तो (शर्तिया वाक्य)", "If... then conditional sentences", "UH-gur ... toh", "अगर तुम मेहनत करोगे, तो अवश्य सफल होगे।", "If you work hard, you will surely succeed.", "Conditional clauses link cause and consequence gracefully.")
                else -> CurriculumLessonContent("हिंदी पॉडकास्ट और श्रवण अभ्यास", "Hindi podcasts and listening practice", "SHRUH-vuhn uhb-HYAAS", "रेडियो और समाचार सुनकर अपनी समझ को गहरा करना।", "Deepening comprehension by listening to radio and news broadcasts.", "Listen for nuanced aspirated consonants (kh, gh, th, dh).")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("एक समय की बात है...", "Once upon a time...", "ayk SUH-muy kee baat", "पंचतंत्र की कहानियों में जीवन के गहरे सबक छिपे हैं।", "Panchatantra fables conceal profound life lessons.", "Panchatantra stories use animal characters to teach worldly wisdom.")
                "Workplace Conversations" -> CurriculumLessonContent("कार्यक्षेत्र में सहयोग और प्रगति", "Workplace cooperation and progress", "KAAR-yuh-ksheh-truh", "कल की बैठक में नई परियोजना के लक्ष्यों की समीक्षा होगी।", "Tomorrow's meeting will review the objectives of the new project.", "Professional Hindi balances Hindi vocabulary with common business terms.")
                "Social Situations" -> CurriculumLessonContent("अतिथि देवो भव (मेहमान भगवान समान)", "Guest is akin to God", "uh-TEE-thee DAY-voh BHAH-vuh", "हमारे घर पधारने के लिए आपका हृदय से आभार।", "Heartfelt thanks to you for gracing our home with your presence.", "The Sanskrit ethic 'Atithi Devo Bhava' underpins Indian hospitality.")
                "News & Media" -> CurriculumLessonContent("दैनिक समाचार और संपादकीय", "Daily news and editorials", "suhm-paa-duh-KEE-yuh", "अखबार में देश के आर्थिक विकास पर विस्तृत विश्लेषण छपा है।", "The newspaper published a detailed analysis of national economic growth.", "Journalistic Hindi uses refined vocabulary.")
                "Idiomatic Expressions" -> CurriculumLessonContent("दाल में कुछ काला होना", "Something is fishy", "daal mein kooch KAA-laa", "उनकी बातों से लगता है कि दाल में कुछ काला है।", "From their words, it feels like something is fishy.", "A beloved Hindi idiom expressing suspicion.")
                else -> CurriculumLessonContent("सकर्मक क्रिया और 'ने' का प्रयोग", "Transitive verbs and the 'ne' postposition", "suh-KUR-muk KREE-yaa", "राहुल ने एक सुंदर कविता लिखी।", "Rahul wrote a beautiful poem.", "'Ne' marks the subject in past tense of transitive verbs.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("सामाजिक बदलाव और युवा पीढ़ी", "Social transformation and the youth generation", "SAA-maa-jik bud-LAAV", "डिजिटल क्रांति ने भारतीय समाज की रूपरेखा बदल दी है।", "The digital revolution has reshaped the landscape of Indian society.", "Articulate socio-economic viewpoints with precision.")
                "Debate & Opinions" -> CurriculumLessonContent("ससम्मान असहमति व्यक्त करना", "Expressing respectful disagreement", "suh-suhm-MAAN", "मैं आपके दृष्टिकोण का सम्मान करते हुए भिन्न मत रखता हूँ।", "While respecting your viewpoint, I hold a different opinion.", "Cultured debate balances civility with firmness.")
                "Abstract Topics" -> CurriculumLessonContent("वसुधैव कुटुम्बकम् की भावना", "The world is one family", "vuh-SOO-dhy-vuh koo-TOOM-buh-kum", "समस्त मानवता को एक परिवार मानने का प्राचीन भारतीय विचार।", "The ancient Indian philosophy regarding all humanity as one single family.", "A guiding principle of Indian diplomacy and ethics.")
                "Natural Expressions" -> CurriculumLessonContent("दिन-रात एक करना / हवा का रुख", "Work day and night / The way wind blows", "din-RAAT ayk kur-naa", "परीक्षा में अव्वल आने के लिए उसने दिन-रात एक कर दिया।", "To top the exam, she worked tirelessly day and night.", "Vivid idioms reflecting relentless effort.")
                "Listening Comprehension" -> CurriculumLessonContent("साहित्यिक संगोष्ठी का श्रवण", "Listening to literary symposiums", "SAA-hit-yik suhn-gohsh-thee", "कवियों के गहन भावों और भाषा के अलंकारों को समझना।", "Understanding the profound emotions of poets and linguistic embellishments.", "Follow rapid spoken Hindi with poetic cadences.")
                else -> CurriculumLessonContent("तर्कसंगत निबंध और विचार", "Logical essay writing and contemplation", "turk-SUHN-gut nee-BUNDH", "प्रस्तावना से निष्कर्ष तक एक सुसंगत तर्क प्रस्तुत करना।", "Presenting a coherent argument from introduction to conclusion.", "Scholarly Hindi composition.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("नीतिगत और रणनीतिक चर्चा", "Policy and strategic deliberations", "NEE-tee-gut chuhr-CHAA", "दूरगामी परिणामों को ध्यान में रखकर ही निर्णय लेना चाहिए।", "Decisions must be made keeping far-reaching consequences in mind.", "Executive administrative Hindi.")
                "Cultural Context" -> CurriculumLessonContent("कबीर, तुलसी और मीरा की वाणी", "The timeless poetry of Kabir, Tulsi, and Meera", "kuh-BEER, tool-SEE, MEE-raa", "कबीर के दोहे जीवन के शाश्वत सत्यों को सरलता से उजागर करते हैं।", "Kabir's couplets effortlessly illuminate timeless truths of human existence.", "Bhakti literature is the heartbeat of North Indian heritage.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("अविचल, निस्वार्थ और शाश्वत", "Unwavering, selfless, and eternal", "uh-vee-CHUL / nees-WAARTH", "देश के प्रति उनका प्रेम निस्वार्थ और अटूट था।", "His love for the country was selfless and unbreakable.", "Rich Sanskrit-derived Tatsam vocabulary.")
                "Advanced Listening" -> CurriculumLessonContent("विभिन्न क्षेत्रीय लहजों की पहचान", "Identifying regional Hindi accents", "ksheh-TREE-yuh luh-HAY-jay", "भोजपुरी, अवधी और राजस्थानी लहजों के वैशिष्ट्य को पहचानना।", "Recognizing the unique flavors of Bhojpuri, Awadhi, and Rajasthani accents.", "Hindi boasts rich dialectal diversity across states.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("प्रशासनिक भाषा बनाम बोलचाल", "Administrative prose versus colloquial speech", "pruh-SHAA-suh-nik BHAASH-aa", "सरकारी पत्राचार में प्रयुक्त औपचारिक शब्दावली का सटीक ज्ञान।", "Accurate mastery of formal terminology used in official correspondence.", "Navigating between street Hindi and Rajbhasha.")
                else -> CurriculumLessonContent("समास और संधि के नियम", "Rules of compound words and phonological joining", "suh-MAAS owr suhn-dhee", "संस्कृत से विकसित शब्दों की संरचना को वैज्ञानिक रूप से समझना।", "Scientifically understanding the structure of Sanskrit-derived words.", "Grammatical precision in classical Hindi.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("व्यापारिक अनुबंध और समझौता", "Commercial contracts and agreements", "vyaa-puh-RIK uh-noo-BUNDH", "दोनों कंपनियों ने द्विपक्षीय व्यापार समझौते पर हस्ताक्षर किए।", "Both companies signed the bilateral trade agreement.", "High corporate, banking, and legal Hindi.")
                "Advanced Reading" -> CurriculumLessonContent("मुंशी प्रेमचंद के अमर उपन्यास", "Munshi Premchand's immortal novels", "MOON-shee praym-CHUND", "गोदान में ग्रामीण भारत के यथार्थ का सजीव चित्रण मिलता है।", "Godan offers a vivid depiction of the realities of rural India.", "Premchand is revered as the emperor of Hindi fiction (Upanyas Samrat).")
                "Idioms & Expressions" -> CurriculumLessonContent("लोहे के चने चबाना", "Overcoming formidable odds (chewing iron chickpeas)", "LOH-hay kay chuh-nay", "कठिन परिस्थितियों में भी उसने लोहे के चने चबाकर जीत हासिल की।", "Even under severe hardships, he persevered through fire to win.", "Emphasizes heroic endurance in adversity.")
                "Advanced Writing" -> CurriculumLessonContent("शोध-पत्र और अकादमिक लेखन", "Research dissertations and academic writing", "SHOHDH-putruh", "प्रामाणिक आँकड़ों और तर्कों के आधार पर शोध निष्कर्ष निकालना।", "Drawing research conclusions on the foundation of verified data and reasoning.", "Standard publishable scholarly Hindi.")
                "Difficult Listening" -> CurriculumLessonContent("संसदीय वाद-विवाद और प्रत्यक्ष प्रसारण", "Parliamentary debates and live broadcasts", "suhn-suh-DEE-yuh vaad-vee-VAAD", "तीखे सवालों और त्वरित प्रत्युत्तरों को बिना किसी रुकावट समझना।", "Comprehending pointed queries and rapid retorts without any hesitation.", "Real-time acoustic mastery of rapid debate.")
                else -> CurriculumLessonContent("मातृभाषी जैसी सहज अभिव्यक्ति", "Native-level effortless expression", "MAA-truh-bhaash-ee", "गंभीर से गंभीर विषय पर भी धाराप्रवाह और प्रभावशाली वक्तव्य।", "Fluent and impactful discourse on even the most profound topics.", "Effortless bilingual mastery.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("सहज, मधुर और धाराप्रवाह हिंदी", "Effortless, sweet, and fluent Hindi", "DHAA-raa-pruh-vaah", "बातचीत में स्वाभाविकता और आत्मीयता का अनूठा संगम।", "A unique harmony of natural ease and warmth in conversation.", "Native fluency with zero hesitation.")
                "Humor & Cultural References" -> CurriculumLessonContent("हास्य-व्यंग्य और हाजिरजवाबी", "Satirical wit and ready repartee", "HAAS-yuh vyung-yuh", "हरिशंकर परसाई के तीखे व्यंग्य और सामाजिक कटाक्ष को समझना।", "Understanding Harishankar Parsai's sharp satire and social critique.", "Appreciating subtle cultural humor.")
                "Advanced Debates" -> CurriculumLessonContent("ओजस्वी वक्तृत्व कला", "Commanding oratorical excellence", "oh-JUS-vee vuk-TRUT-vuh", "अपने ओजस्वी भाषण से विशाल जनसमूह को मंत्रमुग्ध करना।", "Mesmerizing vast assemblies with commanding and eloquent speech.", "Mastery over public rhetoric.")
                "Professional Fluency" -> CurriculumLessonContent("वैश्विक मंच पर नेतृत्व", "Leadership on the global stage", "VAYSH-vik munch", "अंतरराष्ट्रीय सम्मेलनों में राष्ट्र का प्रतिनिधित्व करना।", "Representing the nation in international leadership symposiums.", "Supreme diplomatic and corporate fluency.")
                "Native-Speed Listening" -> CurriculumLessonContent("त्वरित श्रवण बोध", "Instant auditory comprehension", "TUH-rit SHRUH-vuhn", "विभिन्न प्रांतों के लोगों की त्वरित बातचीत को सहजता से ग्रहण करना।", "Effortlessly absorbing rapid multi-regional conversations in real time.", "Full acoustic discernment.")
                else -> CurriculumLessonContent("पूर्ण भाषाई एवं सांस्कृतिक समरसता", "Complete linguistic and cultural harmony", "suhm-ruh-SUH-taa", "हिंदी की आत्मा, संस्कृति और दर्शन को आत्मसात कर जीवन जीना।", "Living life absorbing the soul, culture, and philosophy of Hindi.", "Total cultural immersion and mastery.")
            }
        }
    }
}

object TamilCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("வணக்கம்! / காலை வணக்கம்", "Vanakkam! / Good morning", "vah-NUHK-kuhm / KAA-lai vah-NUHK-kuhm", "வணக்கம்! நீங்கள் எப்படி இருக்கிறீர்கள்?", "Vanakkam! How are you?", "The traditional Tamil greeting honoring the divine within all beings.")
                "Introducing Yourself" -> CurriculumLessonContent("என் பெயர் அன்பு", "My name is Anbu", "en PEY-ar UHN-boo", "என் பெயர் அன்பு, நான் சென்னையில் வசிக்கிறேன்.", "My name is Anbu, I reside in Chennai.", "'En peyar' (my name) is the standard polite introduction.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("ஆம் / இல்லை / தயவுசெய்து / நன்றி", "Yes / No / Please / Thank you", "aam / EEL-lai / THUH-yuh-voo-say-dhoo / NUHN-dree", "ஆம், எனக்கு உதவி செய்யுங்கள். மிக்க நன்றி!", "Yes, please help me. Many thanks!", "'Nandri' expresses sincere gratitude.")
                "Numbers 1–10" -> CurriculumLessonContent("ஒன்று, இரண்டு, மூன்று, நான்கு, ஐந்து...", "1 to 10 numerals", "OHN-druh, ee-RUHN-doo, MOON-druh", "எனக்கு இரண்டு கப் தேநீர் வேண்டும்.", "I want two cups of tea, please.", "Tamil numerals have distinct classical glyphs (௧, ௨, ௩).")
                "Basic Pronouns" -> CurriculumLessonContent("நான், நீ, நீங்கள், நாம், அவர்கள்", "I, you (informal), you (formal), we, they", "naan, nee, NEENG-guhl, naam, uh-VUHR-guhl", "நாம் அனைவரும் தமிழ் மொழியைக் கற்கிறோம்.", "We are all learning the Tamil language.", "'Neengal' is polite and respectful; 'nee' is for close younger peers.")
                else -> CurriculumLessonContent("மன்னிக்கவும் மற்றும் மீண்டும் சந்திப்போம்", "Excuse me / Sorry and See you again", "MUHN-neek-kuh-vuhm / MEEN-doom suhn-DHEEP-pohm", "மன்னிக்கவும், பேருந்து நிலையம் எங்கே உள்ளது?", "Excuse me, where is the bus stand located?", "'Meendum sandhippom' is the warm farewell phrase.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("குடும்பம் (அம்மா, அப்பா, அண்ணன், தங்கை)", "Family (mother, father, elder brother, younger sister)", "koo-DOOM-buhm", "என் அண்ணன் பொறியாளராக வேலை செய்கிறார்.", "My elder brother works as an engineer.", "Tamil distinguishes elder (annan/akka) and younger (thambi/thangai) siblings.")
                "Colors" -> CurriculumLessonContent("சிவப்பு, நீலம், மஞ்சள், பச்சை, வெள்ளை", "Red, Blue, Yellow, Green, White", "shee-VAHP-poo, NEE-luhm, MUHN-juhl", "அந்தப் பச்சைப் புடவை மிகவும் அழகாக இருக்கிறது.", "That green saree is very beautiful.", "Color adjectives precede nouns in Tamil.")
                "Food" -> CurriculumLessonContent("இட்லி, தோசை, சாம்பார் மற்றும் சோறு", "Idli, dosa, sambar, and rice", "EED-lee, DHOH-sai, SAAM-baar", "சுடச்சுட இட்லியும் சாம்பாரும் மிகச் சுவையாக இருக்கும்.", "Hot steaming idlis with sambar are delicious.", "South Indian food is traditionally served on clean banana leaves.")
                "Days & Months" -> CurriculumLessonContent("திங்கள் முதல் ஞாயிறு வரை", "Monday to Sunday", "THEENG-guhl moo-dhal NYAA-yee-roo", "சனிக்கிழமை மாலை கடற்கரைக்குச் செல்வோம்.", "On Saturday evening we will go to the beach.", "Tamil calendar days are tied to astronomical planetary names.")
                "Simple Questions" -> CurriculumLessonContent("யார்? என்ன? எங்கே? எப்போது? ஏன்?", "Who? What? Where? When? Why?", "yaar, EN-nuh, eng-GAY, ep-POH-dhoo, ayn", "தொடர்வண்டி நிலையம் எங்கே இருக்கிறது?", "Where is the railway station situated?", "Question words in Tamil often carry an interrogative 'e' prefix.")
                else -> CurriculumLessonContent("சாப்பிடு, குடி, வா, போ", "Eat, drink, come, go", "SAAP-pee-doo, KOO-dee, vaa, poh", "நண்பர்களுடன் மாலையில் பூங்காவிற்குப் போகிறேன்.", "I go to the park in the evening with friends.", "Verbs conjugate politely with '-ungal' endings for elders.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("காலை எழுந்திருத்தல் மற்றும் நடைப்பயிற்சி", "Waking up in the morning and walking", "KAA-lai eh-zhoon-dhee-ROOT-thuhl", "நான் தினமும் காலை ஆறு மணிக்கு எழுந்திருப்பேன்.", "I wake up at six o'clock every morning.", "Daily routines reflect disciplined traditional lifestyle.")
                "Shopping" -> CurriculumLessonContent("இதன் விலை என்ன?", "What is the price of this?", "ee-DHUHN vee-lai EN-nuh", "அண்ணா, இந்த மாம்பழத்தின் விலை என்ன?", "Brother, what is the price of this mango?", "Addressing market vendors as 'Anna' (elder brother) creates instant rapport.")
                "Time" -> CurriculumLessonContent("இப்போது மணி என்ன?", "What is the time now?", "eep-POH-dhoo MUHN-ee", "இப்போது பிற்பகல் இரண்டரை மணி ஆகிறது.", "It is 2:30 in the afternoon right now.", "'Arai' signifies half past the hour in Tamil.")
                "Directions" -> CurriculumLessonContent("நேராகச் செல்லுங்கள், வலதுபுறம் திரும்புங்கள்", "Go straight, turn right", "NAY-rah-gah, VUH-luh-dhoo-poo-ruhm", "நேராகச் சென்று அடுத்த சந்தில் இடதுபுறம் திரும்புங்கள்.", "Go straight and turn left at the next street.", "'Valadhu' is right, 'idhadhu' is left.")
                "Simple Sentences" -> CurriculumLessonContent("நான் தமிழ் புத்தகம் படிக்க விரும்புகிறேன்", "I want to read a Tamil book", "vee-ROOM-boo-gee-rayn", "மாலையில் கடற்கரையில் காற்று வாங்க விரும்புகிறேன்.", "I want to enjoy the breeze at the beach in the evening.", "Pattern: Infinitive verb + 'virumbugiraen'.")
                else -> CurriculumLessonContent("நலமாக இருக்கிறீர்களா?", "Are you doing well?", "nuh-Luh-MAA-gah ee-rook-kee-reeng-guh-laa", "நான் நலமாக இருக்கிறேன், உங்கள் குடும்பத்தினர் எப்படி?", "I am doing well, how is your family?", "A caring and culturally warm check-in phrase.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("நேற்று நான் மதுரை மீனாட்சி அம்மன் கோவில் சென்றேன்", "Yesterday I went to Madurai Meenakshi Temple", "NAY-truh naan MUH-dhoo-rai", "நேற்று வரலாற்றுச் சிறப்புமிக்க கோவிலை வழிபட்டோம்.", "Yesterday we visited the historically renowned temple.", "Past tense markers (-th-, -nd-, -tt-) reflect verb classification.")
                "Future Plans" -> CurriculumLessonContent("அடுத்த வாரம் ஊட்டிக்குச் செல்வோம்", "Next week we will travel to Ooty", "UH-dhoot-thuh VAA-ruhm", "கோடை விடுமுறையில் நாங்கள் மலைவாசஸ்தலம் செல்வோம்.", "During summer vacation we will travel to a hill station.", "Future tense conjugations express pleasant anticipation.")
                "Travel" -> CurriculumLessonContent("தமிழ்நாடு அரசு விரைவுப் பேருந்து", "Tamil Nadu State Express Bus", "TOH-duhr-vuhn-dee", "சென்னை செல்லும் விரைவுப் பேருந்து தயாராக உள்ளது.", "The express bus heading to Chennai is ready.", "Buses and trains form the lifeblood of Tamil Nadu transit.")
                "Restaurants" -> CurriculumLessonContent("ரசீது கொண்டு வாருங்கள்", "Please bring the bill", "RUH-see-dhoo kohn-doo", "உணவு மிகச் சுவையாக இருந்தது, ரசீது கொடுங்கள்.", "The meal was exquisite, please give the bill.", "Filter coffee (Degree Kaapi) is the iconic finale of a Tamil meal.")
                "Describing People" -> CurriculumLessonContent("அன்பான, பண்பான மற்றும் அறிவார்ந்த", "Loving, cultured, and knowledgeable", "UHN-baa-nuh, PUHN-baa-nuh", "எங்கள் ஆசிரியர் மிகுந்த பொறுமையும் அன்பும் உடையவர்.", "Our teacher possesses tremendous patience and warmth.", "Adjectives in Tamil gracefully end in '-aana'.")
                else -> CurriculumLessonContent("இன்று இதமான தென்றல் வீசுகிறது", "A pleasant gentle breeze blows today", "ee-DHUH-maa-nuh THEN-ruhl", "மாலை வேளையில் இதமான கடற்கரைக் காற்று வீசுகிறது.", "In the evening, a pleasant ocean breeze is blowing.", "The southern sea breeze ('Thendral') is celebrated in Tamil poetry.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("என் கருத்தைப் பகிர்ந்துகொள்ளலாமா?", "May I share my perspective?", "KAR-oot-thai pah-GEERN-dhoo", "இந்தத் திட்டத்தைப் பற்றி சில ஆலோசனைகளைக் கூறலாமா?", "May I offer some suggestions regarding this plan?", "Polite formal conversational participation.")
                "Opinions" -> CurriculumLessonContent("என் கருத்துப்படி கல்வி மிக முக்கியம்", "In my opinion, education is paramount", "en kahr-ROOT-thoo-ppuh-dee", "என் கருத்துப்படி, தாய்மொழி வழிக் கல்வியே சிறந்தது.", "In my view, mother-tongue education is supreme.", "'En karuthuppadi' introduces grounded viewpoints.")
                "Experiences" -> CurriculumLessonContent("மறக்க முடியாத பயண அனுபவங்கள்", "Unforgettable travel experiences", "muh-RUHK-kuh moo-DEE-yaa-dhuh", "கன்னியாகுமரியில் சூரிய உதயத்தைக் கண்டது மறக்க முடியாதது.", "Watching the sunrise at Kanyakumari was unforgettable.", "Relating profound life memories.")
                "Comparisons" -> CurriculumLessonContent("சென்னையை விட தஞ்சாவூர் அமைதியானது", "Thanjavur is calmer than Chennai", "CHEN-nai-yai vee-duh", "கிராமப்புற வாழ்க்கை நகரத்தை விட அமைதியானது.", "Rural life is much more peaceful than city life.", "The suffix '-ai vida' marks comparative distinction.")
                "More Complex Grammar" -> CurriculumLessonContent("ஆனால் / ஏனென்றால் (இணைப்புச் சொற்கள்)", "But / Because (conjunctions)", "AA-naal / AY-nen-raal", "மழை பெய்தது, ஆனாலும் நாங்கள் நிகழ்வுக்குச் சென்றோம்.", "It rained, yet we went to the event.", "Conjunctions create fluid, multi-clause Tamil sentences.")
                else -> CurriculumLessonContent("தமிழ் வானொலி கேட்டல் பயிற்சி", "Tamil radio listening practice", "VAA-noh-lee KAYT-tuhl", "வானொலிச் செய்திகளைக் கூர்ந்து கவனித்துக் கேட்கிறேன்.", "I listen attentively to radio news broadcasts.", "Distinguishing literary written Tamil from spoken colloquial Tamil.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("முன்னொரு காலத்தில் ஒரு காட்டில்...", "Once upon a time in a forest...", "MOON-noh-roo KAA-luh-theel", "தெனாலிராமன் கதைகள் புத்திக்கூர்மையை வெளிப்படுத்துகின்றன.", "Tenali Raman stories demonstrate sharp intellectual wit.", "Tenali Raman tales blend humor with clever moral resolutions.")
                "Workplace Conversations" -> CurriculumLessonContent("அலுவலகக் கலந்தாய்வுக் கூட்டம்", "Office consultative meeting", "uh-LOO-vuh-luh-guh", "புதிய திட்டத்தின் முன்னேற்றம் குறித்து விரிவாக விவாதித்தோம்.", "We discussed the progress of the new project in detail.", "Modern corporate Tamil functions smoothly across IT corridors.")
                "Social Situations" -> CurriculumLessonContent("யாதும் ஊரே யாவரும் கேளிர்", "Every town is our hometown; everyone is kin", "YAA-dhoom OO-ray YAA-vuh-room KAY-leer", "அனைவரையும் குடும்பமாக வரவேற்கும் உன்னத பண்பாடு.", "The noble culture of welcoming all humanity as one family.", "Ancient Sangam poem verse reflecting universal brotherhood.")
                "News & Media" -> CurriculumLessonContent("நாளிதழ் செய்திகள் மற்றும் தலையங்கம்", "Daily newspaper headlines and editorials", "NAA-lee-dhuhl SAY-dhee-guhl", "செய்தித்தாளில் பொருளாதார வளர்ச்சி பற்றிய தலையங்கம் வந்துள்ளது.", "An editorial regarding economic growth appeared in the paper.", "Written media uses dignified Senthamizh phrasing.")
                "Idiomatic Expressions" -> CurriculumLessonContent("சிறு துளி பெரு வெள்ளம்", "Every little drop makes a mighty flood", "SHEE-roo THOO-lee", "சிறிய சேமிப்பும் பிற்காலத்தில் பெரும் பலன் தரும்.", "Even small savings will yield tremendous benefit in the future.", "Proverb emphasizing patience and continuous effort.")
                else -> CurriculumLessonContent("வினையெச்சம் மற்றும் பெயரெச்சம்", "Adverbial and adjectival participles", "vee-NAI-yech-chuhm", "படித்து முடித்த புத்தகத்தை மீண்டும் வாசித்தேன்.", "I reread the book that I had completed reading.", "Participles link clauses elegantly without repeating subjects.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("சமூக விழிப்புணர்வும் முன்னேற்றமும்", "Social awareness and progress", "suh-MOO-guh vee-zheep-POO-nahr-voo", "சமத்துவமும் கல்வி வளர்ச்சியுமே சமுதாயத்தின் இரு கண்கள்.", "Equality and educational progress are the two eyes of society.", "Articulating social justice themes in cultured Tamil.")
                "Debate & Opinions" -> CurriculumLessonContent("பட்டிமன்ற விவாத நடை", "Pattimandram debate style", "puht-tee-MUHN-druhm", "இரு தரப்பு நியாயங்களையும் சீர்தூக்கிப் பார்த்துத் தீர்ப்பளித்தல்.", "Weighing the merits of both sides before delivering judgment.", "Pattimandram is Tamil Nadu's celebrated oral debate art.")
                "Abstract Topics" -> CurriculumLessonContent("செம்மொழித் தமிழின் தொன்மையும் வளமும்", "Antiquity and richness of Classical Tamil", "sehm-MOH-zhee", "இரண்டாயிரத்திற்கும் மேற்பட்ட ஆண்டுகள் தொடர்ச்சியான இலக்கிய வளம்.", "Continuous literary heritage spanning over two millennia.", "Tamil is recognized globally as an ancient classical tongue.")
                "Natural Expressions" -> CurriculumLessonContent("கண் துடைப்பு / கை கூடுதல்", "Mere eye-wash / Culminating in success", "KUHN thoo-DAI-ppoo", "நீண்ட நாள் முயற்சி இன்று வெற்றிகரமாகக் கை கூடியது.", "A long-standing effort has culminated successfully today.", "Expressive idioms enrich natural spoken discourse.")
                "Listening Comprehension" -> CurriculumLessonContent("மேடைப் பேச்சைக் கூர்ந்து கவனித்தல்", "Attentively following public speeches", "MAY-dai-ppay-choo", "அறிஞர்களின் செறிவான உரையைக் குறிப்பெடுத்துக் கேட்டல்.", "Taking notes while listening to scholars' erudite lectures.", "Comprehending rapid alliterative Tamil rhetoric (Edhugai and Monai).")
                else -> CurriculumLessonContent("ஆராய்ச்சி அறிக்கை தயாரித்தல்", "Preparing research reports", "aa-RAA-eech-chee uh-REEK-kai", "சான்றுகளின் அடிப்படையில் முறையான கட்டுரையை வரைதல்.", "Drafting a systematic essay on the basis of verified evidence.", "Formal composition in standard academic Tamil.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("தொலைநோக்குப் பார்வை மற்றும் கொள்கை", "Farsighted vision and policy", "thoh-lai-NOHK-koo", "நீண்டகால விளைவுகளைக் கருத்தில் கொண்டே முடிவெடுக்க வேண்டும்.", "Decisions must be made factoring in long-term implications.", "Executive administrative Tamil terminology.")
                "Cultural Context" -> CurriculumLessonContent("திருக்குறள் அறநெறிக் கோட்பாடுகள்", "Thirukkural moral and ethical philosophy", "thee-ROOK-koo-ruhl", "அன்பும் அறனும் உடைத்தாயின் இல்வாழ்க்கை பண்பும் பயனும் அது.", "Love and righteousness constitute the hallmark and reward of life.", "Thiruvalluvar's universal ethical couplets.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("அருஞ்சொற்கள் மற்றும் நுட்பமான பொருள்", "Rare words and subtle nuances", "uh-ROON-johr-kuhl", "இலக்கியத்தில் பொதிந்துள்ள நயமான சொற்சுவைகளை உணர்தல்.", "Savoring the delicate linguistic flavors embedded in literature.", "Elevated classical vocabulary.")
                "Advanced Listening" -> CurriculumLessonContent("வட்டார வழக்குகளைப் பிரித்தறிதல்", "Distinguishing regional Tamil dialects", "vuht-TAA-ruh VUH-zhuhk-koo", "கொங்கு, நெல்லை, மற்றும் மதுரைத் தமிழ் வழக்குகளைப் புரிதல்.", "Understanding Kongu, Nellai, and Madurai dialectal inflections.", "Appreciating the melodic variety across Tamil regions.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("செந்தமிழும் கொச்சைத் தமிழும்", "Formal Classical Tamil vs Colloquial Tamil", "sehn-TUH-mil / kohch-CHAI", "மேடைப் பேச்சுக்கும் அன்றாடப் பேச்சுக்கும் உள்ள வேறுபாடு.", "The clear distinction between platform oration and casual conversation.", "Mastering register shifts effortlessly.")
                else -> CurriculumLessonContent("இலக்கண மரபுகள் மற்றும் தொல்காப்பியம்", "Grammatical traditions and Tholkappiyam", "thohl-KAAP-pee-yuhm", "பழமையான தமிழ் இலக்கணத்தின் அறிவியல் பூர்வமான கட்டமைப்பு.", "The scientific structural foundations of ancient Tamil grammar.", "Tholkappiyam is the oldest extant grammar treatise.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("வணிக ஒப்பந்தங்களும் உடன்படிக்கைகளும்", "Commercial contracts and covenants", "vuh-NEE-guh ohp-puhn-DHUH-guhl", "இரு நிறுவனங்களும் அதிகாரப்பூர்வக் கூட்டு ஒப்பந்தத்தில் கையெழுத்திட்டன.", "Both institutions signed the official partnership accord.", "Corporate, legal, and international trade Tamil.")
                "Advanced Reading" -> CurriculumLessonContent("சிலப்பதிகாரமும் கம்பராமாயணமும்", "Silappadikaram and Kamba Ramayanam epics", "shee-luhp-puh-dhee-GAA-ruhm", "காவியங்களின் கவிதை நயத்தையும் உணர்ச்சிகளையும் ஆய்ந்தறிதல்.", "Analyzing poetic elegance and profound emotional depth in classical epics.", "Supreme literary appreciation.")
                "Idioms & Expressions" -> CurriculumLessonContent("முயற்சி திருவினையாக்கும்", "Hard work yields prosperity", "moo-YUHR-chee thee-roo-vee-NAI", "விடாமுயற்சியோடு உழைப்பவர்க்கு வெற்றி நிச்சயம்.", "Success is certain for those who labor with persevering diligence.", "Ethical proverb celebrating human industry.")
                "Advanced Writing" -> CurriculumLessonContent("ஆய்வுக் கட்டுரைகளும் திறனாய்வும்", "Research dissertations and critical critiques", "aa-ee-VOOK kuhl-TOO-rai", "நடுநிலையான ஆய்வு முறையியலுடன் கருத்தை நிறுவுதல்.", "Establishing conclusions using objective research methodology.", "High publishable prose.")
                "Difficult Listening" -> CurriculumLessonContent("சட்டமன்ற விவாதங்கள் மற்றும் வாதங்கள்", "Legislative debates and legal court arguments", "suht-tuh-MUHN-druh vee-VAA-dhum", "வேகமான கருத்துப் பரிமாற்றங்களை உடனுக்குடன் புரிந்துகொள்ளுதல்.", "Grasping fast-paced rhetorical interchanges in real time.", "Supreme auditory discernment.")
                else -> CurriculumLessonContent("தாய்மொழிப் புலமையின் முழு நிறைவு", "Complete native mastery of language", "thaai-MOH-zhee", "சொல்லாட்சியும் நாவன்மையும் கொண்டு எந்தப் பொருளையும் விளக்குதல்.", "Explaining any subject with command over words and eloquence.", "Effortless bilingual command.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("இயல்பான, சரளமான உரையாடல் திறன்", "Natural, fluent conversational ability", "suh-ruh-Luh-MAA-nuh", "தயக்கமின்றி இனிமையாகவும் தடையின்றியும் பேசுதல்.", "Speaking sweetly and unimpeded without a trace of hesitation.", "Native cadence and warmth.")
                "Humor & Cultural References" -> CurriculumLessonContent("சுவையான சிலேடையும் நகைச்சுவையும்", "Delightful wordplay and cultured humor", "shee-LAY-dai / nuh-gai-CHOO-vai", "இரட்டை அர்த்த சிலேடைப் பேச்சுகளைச் சுவைத்து ரசித்தல்.", "Savoring delightful double-entendre wordplay in Tamil.", "Subtle cultural humor.")
                "Advanced Debates" -> CurriculumLessonContent("அனல் பறக்கும் வாதத்திறன்", "Fiery and commanding argumentative skill", "uh-NUHL puh-ruh-koom", "நாவன்மையாலும் தர்க்கரீதியான சான்றுகளாலும் அவையை ஈர்த்தல்.", "Captivating the assembly through eloquence and logical evidence.", "Mastery over public oratory.")
                "Professional Fluency" -> CurriculumLessonContent("உலகளாவிய தமிழர்களின் தலைமைத்துவம்", "Leadership across the global Tamil diaspora", "oo-luh-guh-LAA-vee-yuh", "பன்னாட்டு மாநாடுகளில் தலைமையுரையாற்றும் ஆளுமை.", "Personality suited to delivering keynote addresses at global summits.", "Executive diaspora leadership.")
                "Native-Speed Listening" -> CurriculumLessonContent("மின்னல் வேக உரையாடலைப் புரிதல்", "Understanding lightning-fast speech", "meen-NUHL VAY-guh", "எவ்வளவு விரைவாகப் பேசினாலும் ஒவ்வொரு சொல்லையும் கிரகித்தல்.", "Absorbing every single word regardless of how rapidly spoken.", "Full auditory mastery.")
                else -> CurriculumLessonContent("முழுமையான தமிழ்ப் பண்பாட்டு ஒன்றிணைவு", "Complete cultural and linguistic oneness with Tamil", "ohn-ree-NAI-voo", "தமிழ் மொழியின் அழகும் அறமும் சிந்தனையிலும் செயலிலும் மலர்தல்.", "The beauty and ethics of Tamil flourishing in thought and action.", "Total cultural and linguistic harmony.")
            }
        }
    }
}

object TeluguCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("నమస్కారం! / శుభోదయం", "Namaskaram! / Good morning", "nuh-muhs-KAA-ruhm / shoo-bhoy-DUH-yuhm", "నమస్కారం! మీరు ఎలా ఉన్నారు?", "Namaskaram! How are you?", "The respectful greeting honoring the divine presence.")
                "Introducing Yourself" -> CurriculumLessonContent("నా పేరు రావు", "My name is Rao", "naa PAY-roo RAA-voo", "నా పేరు రావు, నేను హైదరాబాద్‌లో నివసిస్తున్నాను.", "My name is Rao, I reside in Hyderabad.", "'Naa peru' (my name) is the standard polite introduction.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("అవును / కాదు / దయచేసి / ధన్యవాదాలు", "Yes / No / Please / Thank you", "uh-VOO-noo / KAA-doo / duh-yuh-CHAY-see", "అవును, దయచేసి నాకు సహాయం చేయండి. ధన్యవాదాలు!", "Yes, please help me. Thank you!", "'Dhanyavaadaalu' expresses sincere gratitude.")
                "Numbers 1–10" -> CurriculumLessonContent("ఒకటి, రెండు, మూడు, నాలుగు, ఐదు...", "1 to 10 numerals", "oh-KUH-tee, REHN-doo, MOO-doo", "నాకు రెండు కప్పుల కాఫీ కావాలి.", "I want two cups of coffee, please.", "Telugu numbers have distinctive curved scripts (౧, ౨, ౩).")
                "Basic Pronouns" -> CurriculumLessonContent("నేను, నువ్వు, మీరు, మేము, వారు", "I, you (informal), you (formal), we, they", "NAY-noo, NOOV-voo, MEE-roo, MAY-moo, VAA-roo", "మేమంతా కలిసి తెలుగు నేర్చుకుంటున్నాము.", "We are all learning Telugu together.", "'Meeru' is polite and respectful; 'nuvvu' is for close younger friends.")
                else -> CurriculumLessonContent("క్షమించండి మరియు మళ్లీ కలుద్దాం", "Excuse me / Sorry and See you again", "kshu-MEEN-chuhn-dee / MUL-lee kuh-LOOD-daam", "క్షమించండి, రైల్వే స్టేషన్ ఎక్కడ ఉంది?", "Excuse me, where is the railway station located?", "'Mallee kaluddhaam' is the warm farewell phrase.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("కుటుంబం (అమ్మ, నాన్న, అన్నయ్య, చెల్లెలు)", "Family (mother, father, elder brother, younger sister)", "koo-TOOM-buhm", "మా అన్నయ్య సాఫ్ట్‌వేర్ ఇంజనీర్‌గా పనిచేస్తున్నాడు.", "My elder brother works as a software engineer.", "Telugu distinguishes elder (annayya/akka) and younger (thammudu/chellelu) siblings.")
                "Colors" -> CurriculumLessonContent("ఎరుపు, నీలం, పసుపు, ఆకుపచ్చ, తెలుపు", "Red, Blue, Yellow, Green, White", "EH-roo-poo, NEE-luhm, PUH-soo-poo", "ఆ ఆకుపచ్చ చీర చాలా అందంగా ఉంది.", "That green saree is very beautiful.", "Color adjectives precede nouns.")
                "Food" -> CurriculumLessonContent("బిర్యానీ, అన్నం, పప్పు మరియు కూర", "Biryani, rice, dal, and curry", "beer-YAA-nee, UHN-nuhm, PUHP-poo", "హైదరాబాదీ బిర్యానీ మరియు పప్పు అన్నం చాలా రుచిగా ఉంటాయి.", "Hyderabadi biryani and dal-rice are delicious.", "Andhra and Telangana cuisines are renowned for rich flavors and spices.")
                "Days & Months" -> CurriculumLessonContent("సోమవారం నుండి ఆదివారం వరకు", "Monday through Sunday", "SOH-muh-vaa-ruhm noon-dee AA-dhee-vaa-ruhm", "ఆదివారం సాయంత్రం మేము సినిమాకి వెళ్తాము.", "On Sunday evening we will go to the movies.", "Telugu days of the week correspond to celestial planetary alignments.")
                "Simple Questions" -> CurriculumLessonContent("ఎవరు? ఏమిటి? ఎక్కడ? ఎప్పుడు? ఎందుకు?", "Who? What? Where? When? Why?", "EH-vuh-roo, AY-mee-tee, EHK-kuh-duh, EHP-poo-doo", "బస్ స్టాండ్ ఎక్కడ ఉందో చెప్పగలరా?", "Could you tell me where the bus stand is?", "Telugu question words typically begin with the vowel 'e'.")
                else -> CurriculumLessonContent("తినడం, తాగడం, రావడం, వెళ్లడం", "Eat, drink, come, go", "TEE-nuh-duhm, THAA-guh-duhm", "సాయంత్రం స్నేహితులతో కలిసి ఉద్యానవనానికి వెళ్తాను.", "In the evening I go to the park together with friends.", "Infinitive verbal nouns in Telugu end with '-adam'.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("ఉదయాన్నే నిద్రలేవడం మరియు వ్యాయామం", "Waking up early and exercising", "oo-duh-YAAN-nay", "నేను రోజూ ఉదయం ఆరు గంటలకు నిద్రలేస్తాను.", "I wake up at six o'clock every morning.", "Present habitual verbs end in '-thaanu'.")
                "Shopping" -> CurriculumLessonContent("దీని ధర ఎంత?", "What is the price of this?", "DEE-nee DHOO-ruh EN-thuh", "అన్నా, ఈ మామిడి పండ్ల ధర ఎంత? కొంచెం తగ్గించండి.", "Brother, how much are these mangoes? Please lower it a bit.", "Calling shopkeepers 'Anna' (brother) builds friendly warmth.")
                "Time" -> CurriculumLessonContent("ఇప్పుడు సమయం ఎంతైంది?", "What is the time now?", "eep-POO-doo suh-muh-yuhm", "ఇప్పుడు మధ్యాహ్నం రెండున్నర అయింది.", "It is 2:30 in the afternoon right now.", "'Rendunnara' means two and a half (2:30).")
                "Directions" -> CurriculumLessonContent("తిన్నగా వెళ్లి కుడివైపు తిరగండి", "Go straight and turn right", "TEEN-nuh-gaa, KOO-dee-vy-poo", "ముందుకు తిన్నగా వెళ్లి కూడలి వద్ద ఎడమవైపు తిరగండి.", "Go straight ahead and turn left at the crossroads.", "'Kudi' is right, 'edama' is left.")
                "Simple Sentences" -> CurriculumLessonContent("నేను తెలుగు పుస్తకం చదవాలనుకుంటున్నాను", "I want to read a Telugu book", "chuh-duh-VAA-lun-koon-toon-naa-noo", "సాయంత్రం సరదాగా కాసేపు మాట్లాడాలనుకుంటున్నాను.", "In the evening I want to chat happily for a while.", "Pattern: Verb infinitive + '-lanukuntunnanu'.")
                else -> CurriculumLessonContent("కులాసాగా ఉన్నారా? అంతా క్షేమమేనా?", "Are you well? Everything safe and fine?", "koo-LAA-saa-gaa", "మేము చాలా బాగున్నాము, మీరంతా ఎలా ఉన్నారు?", "We are very good, how are all of you?", "Traditional warm Telugu wellness greeting.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("నిన్న మేము తిరుపతి దర్శనానికి వెళ్లాము", "Yesterday we went for Tirupati darshan", "NEEN-nuh MAY-moo tee-ROO-puh-tee", "నిన్న మేము పవిత్ర దేవాలయాన్ని దర్శించుకున్నాము.", "Yesterday we visited the sacred temple.", "Past tense markers indicate completed pilgrimage.")
                "Future Plans" -> CurriculumLessonContent("వచ్చే నెల వైజాగ్ వెళ్లే ఆలోచన ఉంది", "Planning to travel to Vizag next month", "VUHTS-chay NAY-luh", "సెలవుల్లో మేము బీచ్ నగరమైన విశాఖపట్నం వెళ్తాము.", "During holidays we will go to the beach city Visakhapatnam.", "Future plans express anticipation of coastal journeys.")
                "Travel" -> CurriculumLessonContent("రైలు ప్రయాణం మరియు టిక్కెట్లు", "Train journey and tickets", "RY-loo pruh-YAA-nuhm", "హైదరాబాద్ వెళ్లే ఎక్స్‌ప్రెస్ రైలు ఏ ప్లాట్‌ఫారమ్‌పై వస్తుంది?", "Which platform does the express train to Hyderabad arrive on?", "Railways connect Andhra and Telangana seamlessly.")
                "Restaurants" -> CurriculumLessonContent("బిల్లు తీసుకురండి, దయచేసి", "Please bring the bill", "BEEL-loo tee-soo-koo-RUHN-dee", "భోజనం చాలా అద్భుతంగా ఉంది, బిల్లు ఇవ్వండి.", "The meal was truly wonderful, please give the bill.", "Filter coffee in a brass Davarah-tumbler finishes the meal.")
                "Describing People" -> CurriculumLessonContent("స్నేహపూర్వక, వినయపూర్వక మరియు ప్రతిభావంతుడు", "Friendly, humble, and talented", "snay-huh-POOR-vuh-kuh", "మా గురువుగారు ఎంతో దయామయుడు మరియు విద్వాంసుడు.", "Our teacher is tremendously compassionate and scholarly.", "Adjectives in Telugu gracefully express noble virtues.")
                else -> CurriculumLessonContent("ఈ రోజు వాతావరణం చాలా ఆహ్లాదకరంగా ఉంది", "The weather is very delightful today", "vaa-taa-vuh-ruh-nuhm", "సాయంత్రం వేళ చల్లని గాలి మనస్సుకు హాయినిస్తోంది.", "In the evening, the cool breeze brings soothing peace.", "Delightful weather inspires conversation.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("నా అభిప్రాయాన్ని తెలియజేయవచ్చా?", "May I express my opinion?", "naa uh-bhee-PRAA-yaan-nee", "ఈ ప్రాజెక్ట్ పురోగతిపై కొన్ని సూచనలు ఇవ్వవచ్చా?", "May I give a few suggestions on this project's progress?", "Polite formal conversational participation.")
                "Opinions" -> CurriculumLessonContent("నా ఉద్దేశంలో కళ మరియు సంగీతం", "In my view, art and music", "naa ood-DAY-shuhm-loh", "నా దృష్టిలో శాస్త్రీయ సంగీతం మనస్సుకు ప్రశాంతతను చేకూరుస్తుంది.", "In my view, classical music imparts serene calm to the mind.", "Telugu is called the 'Italian of the East' for vowel-ending words.")
                "Experiences" -> CurriculumLessonContent("మరపురాని తీపి అనుభవాలు", "Unforgettable sweet experiences", "muh-ruh-poo-RAA-nee", "గోదావరి నదిలో పడవ ప్రయాణం చేసిన క్షణాలు మరపురానివి.", "The moments spent boating on the Godavari River are unforgettable.", "Cherishing travel and life memories.")
                "Comparisons" -> CurriculumLessonContent("విజయవాడ కంటే హైదరాబాద్ చాలా పెద్ద నగరం", "Hyderabad is a much bigger city than Vijayawada", "vee-juh-yuh-VAA-duh kahn-tay", "రైలు ప్రయాణం బస్సు కంటే ఎక్కువ సౌకర్యవంతంగా ఉంటుంది.", "Train travel is much more comfortable than by bus.", "'Kante' marks comparative evaluation.")
                "More Complex Grammar" -> CurriculumLessonContent("ఒకవేళ... అయితే (షరతు వాక్యాలు)", "If... then conditional sentences", "oh-kuh-VAY-luh", "ఒకవేళ వర్షం పడితే, మేము ఇంట్లోనే ఉంటాము.", "If it rains, we will stay at home.", "Conditional clauses structure logical causes.")
                else -> CurriculumLessonContent("తెలుగు రేడియో వినడం ద్వారా అభ్యాసం", "Practicing by listening to Telugu radio", "RAY-dee-yoh VEE-nuh-duhm", "ప్రముఖుల ప్రసంగాలు శ్రద్ధగా విని పదసంపద పెంచుకోవడం.", "Enriching vocabulary by listening attentively to eminent speeches.", "Notice the melodic vowel endings of every Telugu word.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("అనగనగా ఒక అందమైన ఊరిలో...", "Once upon a time in a beautiful village...", "uh-nuh-guh-nuh-gaa", "తెనాలి రామకృష్ణుడి చతురత మరియు హాస్య కథలు.", "Tenali Ramakrishna's wit and humorous stories.", "Tenali Ramakrishna served the court of Sri Krishnadevaraya.")
                "Workplace Conversations" -> CurriculumLessonContent("కార్యాలయ సమావేశం మరియు చర్చలు", "Office meeting and discussions", "kaar-yaa-LUH-yuh", "వ్యాపార వ్యూహాలపై భాగస్వాములతో లోతుగా చర్చించాము.", "We discussed business strategies in-depth with partners.", "Modern corporate Telugu blends professionalism with cultural poise.")
                "Social Situations" -> CurriculumLessonContent("అతిథి సత్కారం మరియు ఆప్యాయత", "Honoring guests and warm affection", "uh-TEE-thee suht-KAA-ruhm", "మా ఇంటికి విచ్చేసినందుకు హృదయపూర్వక ధన్యవాదాలు.", "Heartfelt gratitude for gracing our home with your visit.", "Hospitality is treated as a sacred duty in Telugu homes.")
                "News & Media" -> CurriculumLessonContent("వార్తాపత్రిక ముఖ్యాంశాలు మరియు విశ్లేషణ", "Newspaper headlines and analysis", "vaar-taa-puh-TREE-kuh", "ఆర్థిక ప్రగతి మరియు సాంకేతిక విప్లవంపై ప్రత్యేక కథనం.", "A special feature on economic progress and technological revolution.", "Journalistic Telugu employs refined literary phrasing.")
                "Idiomatic Expressions" -> CurriculumLessonContent("చేతులు కాలాక ఆకులు పట్టుకోవడం", "Trying to hold leaves after burning hands (too late)", "CHAY-thoo-loo kaa-laa-kuh", "ముందే జాగ్రత్త పడకపోతే తీరని నష్టం వాటిల్లుతుంది.", "If precautions aren't taken beforehand, irreversible loss occurs.", "Timeless proverb warning against delayed action.")
                else -> CurriculumLessonContent("క్త్వార్థం మరియు చేదర్థం (క్రియా రూపాలు)", "Conjunctive participles and conditionals", "kriy-aa roo-PAA-loo", "పని పూర్తి చేసి సంతోషంగా విశ్రాంతి తీసుకున్నాడు.", "Having completed the work, he rested happily.", "Conjunctive participles link actions effortlessly.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("సామాజిక చైతన్యం మరియు మార్పు", "Social consciousness and transformation", "SAA-maa-jee-kuh chy-THUHN-yuhm", "సమాజ పురోగతికి అక్షరాస్యత మరియు మహిళా సాధికారత మూలస్తంభాలు.", "Literacy and women's empowerment are pillars of societal progress.", "Deliberating social themes in scholarly Telugu.")
                "Debate & Opinions" -> CurriculumLessonContent("హేతుబద్ధమైన వాదన మరియు సమర్థన", "Rational debate and justification", "HAY-thoo-buhd-dhuh", "తమ వాదనలను నిరూపించడానికి బలమైన ఆధారాలు చూపించడం.", "Presenting strong evidence to justify one's line of reasoning.", "Intellectual debate conducted with mutual deference.")
                "Abstract Topics" -> CurriculumLessonContent("తేనె వంటి తియ్యనైన తెలుగు భాషా ప్రాభవం", "Sweetness and glory of honey-like Telugu", "TAY-nay vuhn-tee", "దేశభాషలందు తెలుగు లెస్స అని శ్రీకృష్ణదేవరాయలు కొనియాడారు.", "Sri Krishnadevaraya praised: 'Among languages of the land, Telugu is supreme.'", "Celebrated classical quotation honoring the language.")
                "Natural Expressions" -> CurriculumLessonContent("చెవిలో పూలు పెట్టడం / కంటికి రెప్పలా", "Deceive someone / Protecting like an eyelid", "chay-vee-loh POO-loo", "తల్లి తన బిడ్డను కంటికి రెప్పలా కాపాడుకుంటుంది.", "A mother protects her child like an eyelid guards the eye.", "Vivid cultural idioms.")
                "Listening Comprehension" -> CurriculumLessonContent("సాహిత్య సదస్సుల ప్రసంగాలను గ్రహించడం", "Comprehending literary conference speeches", "SAA-heet-yuh suh-DUHS-soo", "కవుల పద్యాల అంతరార్థాన్ని మరియు భావాన్ని గ్రహించడం.", "Comprehending the inner meaning and emotion of poetic verses.", "Following high-register Telugu with classical cadences.")
                else -> CurriculumLessonContent("పరిశోధనాత్మక వ్యాస రచన", "Investigative scholarly essay writing", "puh-ree-SHOH-dhuh-naat-muh-kuh", "క్రమబద్ధమైన ఉపోద్ఘాతం మరియు నిర్ధారణతో కూడిన వ్యాసం.", "An essay with systematic introduction and conclusive proof.", "Scholarly composition.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("వ్యూహాత్మక ప్రణాళిక మరియు నిర్ణయాలు", "Strategic planning and executive decisions", "vyoo-HAAT-muh-kuh", "దీర్ఘకాలిక ప్రయోజనాలను దృష్టిలో ఉంచుకొని నిర్ణయాలు తీసుకోవడం.", "Taking decisions keeping long-term benefits in perspective.", "Administrative Telugu.")
                "Cultural Context" -> CurriculumLessonContent("త్యాగరాజ కీర్తనలు మరియు కర్ణాటక సంగీతం", "Tyagaraja compositions and Carnatic music", "tyaa-guh-RAA-juh keer-thuh-nuh-loo", "భక్తి మరియు సంగీత సంగమమైన త్యాగయ్య కృతులు జగత్ప్రసిద్ధం.", "Tyagayya's works, merging devotion and music, are world-renowned.", "Carnatic musical heritage is centered on Telugu compositions.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("అనన్యసామాన్యమైన, నిష్కళంకమైన", "Unprecedented, immaculate, and pristine", "uh-nuhn-yuh-saa-MAAN-yuh", "ఆయన చూపిన ప్రతిభ అనన్యసామాన్యమైనది మరియు ఆదర్శప్రాయమైనది.", "The talent he displayed was unprecedented and exemplary.", "Elevated Sanskrit-Telugu vocabulary.")
                "Advanced Listening" -> CurriculumLessonContent("ప్రాంతీయ యాసల వైవిధ్యం", "Diversity of regional Telugu accents", "praang-TEE-yuh YAA-suh-loo", "తెలంగాణ, కోస్తా మరియు రాయలసీమ మాండలికాల అందం.", "The beauty of Telangana, Coastal, and Rayalaseema dialects.", "Rich linguistic diversity across regions.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("గ్రంథిక భాష మరియు శిష్ట వ్యవహారికం", "Literary classical vs Standard spoken Telugu", "GRAHN-thee-kuh BHAASH-uh", "సాహిత్య రచనలలో మరియు రోజువారీ సంభాషణలలో శైలీ భేదాలు.", "Stylistic differences in literary writings versus daily parlance.", "Navigating varied linguistic registers.")
                else -> CurriculumLessonContent("ఛందస్సు మరియు అలంకారాల పరిజ్ఞానం", "Prosody, meter, and poetic embellishments", "CHUN-duhs-soo", "తెలుగు పద్యాల వృత్తాలు మరియు అలంకార సౌందర్యం.", "The meters and decorative beauty of classical Telugu verse.", "Metrical mastery in classical poetry.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("అంతర్జాతీయ వాణిజ్య ఒప్పందాలు", "International commercial treaties", "uhn-thuhr-JAA-tee-yuh", "రెండు దిగ్గజ సంస్థల మధ్య పరస్పర అవగాహన ఒప్పందం కుదిరింది.", "A memorandum of understanding was forged between the two giant firms.", "High corporate and diplomatic Telugu.")
                "Advanced Reading" -> CurriculumLessonContent("శ్రీశ్రీ మహాప్రస్థానం మరియు విశ్వనాథ సత్యనారాయణ", "Sri Sri's Mahaprasthanam and Viswanatha Satyanarayana", "sree-sree muh-haa-pruh-STHAA-nuhm", "ఆధునిక మరియు సాంప్రదాయ సాహిత్య శిఖరాలను ఆస్వాదించడం.", "Savoring both modern progressive and classical literary peaks.", "Reading acclaimed masterworks.")
                "Idioms & Expressions" -> CurriculumLessonContent("ఆకాశానికి నిచ్చెన వేయడం", "Attempting the impossible (ladder to the sky)", "aa-kaa-shaa-NEE-kee", "సాహసోపేతమైన లక్ష్యాలను ఛేదించడానికి దృఢ సంకల్పం అవసరం.", "Firm resolve is essential to overcome audacious targets.", "Proverbs reflecting boundless ambition.")
                "Advanced Writing" -> CurriculumLessonContent("శాస్త్రీయ పరిశోధన మరియు విమర్శ", "Scientific research and literary critique", "SHAA-stree-yuh", "సమగ్ర పరిశీలనతో కూడిన పరిశోధనా పత్రాన్ని ప్రచురించడం.", "Publishing a research paper with thorough investigation.", "Scholarly prose.")
                "Difficult Listening" -> CurriculumLessonContent("శాసనసభ చర్చలు మరియు ప్రత్యక్ష వ్యాఖ్యానం", "Legislative assembly debates and live commentary", "SHAA-suh-nuh-suh-bhuh", "వేగవంతమైన రాజకీయ వాదప్రతివాదాలను స్పష్టంగా విశ్లేషించడం.", "Clearly analyzing rapid political debates and counter-arguments.", "High-speed real-time comprehension.")
                else -> CurriculumLessonContent("మాతృభాషా ప్రావీణ్యం మరియు సమగ్రత", "Native-level eloquence and linguistic integrity", "praa-VEEN-yuhm", "ఏ అంశంపైనైనా అనర్గళంగా, అధికారికంగా మాట్లాడగల సామర్థ్యం.", "Ability to speak effortlessly and authoritatively on any subject.", "Effortless bilingual fluency.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("తేనెలొలుకు సహజ సంభాషణ", "Naturally sweet and eloquent conversation", "suh-huh-juh suhm-BHAA-shuh-nuh", "ఎటువంటి తడబాటు లేకుండా స్వచ్ఛమైన తెలుగులో మాట్లాడటం.", "Speaking in pure Telugu without the slightest hesitation.", "Effortless native cadence.")
                "Humor & Cultural References" -> CurriculumLessonContent("హాస్య చతురత మరియు జానపద వినోదం", "Witty humor and folkloric entertainment", "HAAS-yuh chuh-thoo-RUH-thuh", "నాటకాలు మరియు సినిమాల్లోని చమత్కారాలను హృదయారా ఆస్వాదించడం.", "Wholeheartedly savoring the witty banters in theater and cinema.", "Cultural humor.")
                "Advanced Debates" -> CurriculumLessonContent("గణనీయమైన ఉపన్యాస కళ", "Distinguished and commanding public oration", "oo-puhn-YAA-suh", "తన వాగ్ధాటితో సభికులను మంత్రముగ్ధులను చేయడం.", "Mesmerizing the assembly with commanding oratorical flow.", "Mastery over public rhetoric.")
                "Professional Fluency" -> CurriculumLessonContent("అంతర్జాతీయ స్థాయిలో తెలుగువారి ప్రతిభ", "Telugu leadership on the international stage", "pruh-TEE-bhuh", "ప్రపంచ వేదికలపై తెలుగు సంస్కృతిని సమున్నతంగా నిలపడం.", "Upholding Telugu culture with distinction on global forums.", "Leadership and global excellence.")
                "Native-Speed Listening" -> CurriculumLessonContent("తీక్షణమైన శ్రవణ సామర్థ్యం", "Acute auditory listening capability", "SHRUH-vuh-nuh", "అతి వేగంగా సాగే సంభాషణల్లోని లోతైన భావాలను గ్రహించడం.", "Catching deep emotions even in rapid-fire speech.", "Full acoustic mastery.")
                else -> CurriculumLessonContent("సంపూర్ణ భాషా సంస్కృతీ సమాగమం", "Complete harmony of language and cultural identity", "suhm-POOR-nuh", "తెలుగు భాషా సౌందర్యాన్ని, సంస్కారాన్ని పరిపూర్ణంగా జీవించడం.", "Fully living the beauty, ethics, and spirit of the Telugu language.", "Ultimate linguistic and cultural mastery.")
            }
        }
    }
}
